import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date: Date, days: number): Date {
  const next = startOfDay(date);
  next.setDate(next.getDate() + days);
  return next;
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function mondayIndex(date: Date): number {
  return (date.getDay() + 6) % 7;
}

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [internalDate, setInternalDate] = useState<Date>(value ?? today);
  const selected = value ?? internalDate;
  const [visibleMonth, setVisibleMonth] = useState<Date>(
    new Date(selected.getFullYear(), selected.getMonth(), 1),
  );

  const days = useMemo(() => {
    const first = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 1);
    const total = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + 1, 0).getDate();
    const cells: (Date | null)[] = Array.from({ length: mondayIndex(first) }, () => null);
    for (let day = 1; day <= total; day += 1) {
      cells.push(new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), day));
    }
    return cells;
  }, [visibleMonth]);

  const select = (date: Date) => {
    const normalized = startOfDay(date);
    setInternalDate(normalized);
    setVisibleMonth(new Date(normalized.getFullYear(), normalized.getMonth(), 1));
    onChange(normalized);
  };

  const shiftMonth = (offset: number) => {
    setVisibleMonth(
      (current) => new Date(current.getFullYear(), current.getMonth() + offset, 1),
    );
  };

  const presets: { label: string; date: Date }[] = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: addDays(today, -1) },
    { label: 'Неделя назад', date: addDays(today, -7) },
  ];

  const monthLabel = visibleMonth.toLocaleDateString('ru-RU', {
    month: 'long',
    year: 'numeric',
  });

  return (
    <section
      className="jx-card"
      aria-label="Выбор даты отчёта"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4)',
        padding: 'var(--jx-space-4)',
        borderRadius: 'var(--jx-radius)',
        background: 'var(--jx-surface)',
        color: 'var(--jx-text)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {presets.map((preset) => (
          <Button
            key={preset.label}
            type="button"
            size="sm"
            variant={isSameDay(preset.date, selected) ? 'primary' : 'secondary'}
            aria-pressed={isSameDay(preset.date, selected)}
            onClick={() => select(preset.date)}
          >
            {preset.label}
          </Button>
        ))}
      </div>

      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-2)',
        }}
      >
        <Button
          type="button"
          size="sm"
          variant="ghost"
          aria-label="Предыдущий месяц"
          onClick={() => shiftMonth(-1)}
        >
          ‹
        </Button>
        <span
          aria-live="polite"
          style={{ font: 'var(--jx-font-heading)', textTransform: 'capitalize' }}
        >
          {monthLabel}
        </span>
        <Button
          type="button"
          size="sm"
          variant="ghost"
          aria-label="Следующий месяц"
          onClick={() => shiftMonth(1)}
        >
          ›
        </Button>
      </header>

      <div
        role="grid"
        aria-label={`Календарь, ${monthLabel}`}
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(7, minmax(0, 1fr))',
          gap: 'var(--jx-space-1)',
        }}
      >
        {WEEKDAYS.map((weekday) => (
          <span
            key={weekday}
            role="columnheader"
            style={{
              textAlign: 'center',
              font: 'var(--jx-font-caption)',
              color: 'var(--jx-text-muted)',
              paddingBottom: 'var(--jx-space-1)',
            }}
          >
            {weekday}
          </span>
        ))}

        {days.map((day, index) =>
          day === null ? (
            <span key={`blank-${index}`} aria-hidden="true" />
          ) : (
            <Button
              key={day.toISOString()}
              type="button"
              size="sm"
              role="gridcell"
              variant={isSameDay(day, selected) ? 'primary' : 'ghost'}
              aria-pressed={isSameDay(day, selected)}
              aria-current={isSameDay(day, today) ? 'date' : undefined}
              aria-label={day.toLocaleDateString('ru-RU', {
                day: 'numeric',
                month: 'long',
                year: 'numeric',
              })}
              onClick={() => select(day)}
            >
              {day.getDate()}
            </Button>
          ),
        )}
      </div>

      <footer style={{ font: 'var(--jx-font-caption)', color: 'var(--jx-text-muted)' }}>
        Дата отчёта:{' '}
        {selected.toLocaleDateString('ru-RU', {
          day: '2-digit',
          month: '2-digit',
          year: 'numeric',
        })}
      </footer>
    </section>
  );
}

